+
+describe("time helpers", () => {
+  it("formats dates in UTC", () => {
+    expect(formatDate(T)).toBe("2026-10-05");
+  });
+
+  it("formats timestamps in UTC", () => {
+    expect(formatTimestamp(T)).toBe("2026-10-05 07:03 UTC");
